tools.example:
pts = GeoPosition /@ RandomVariate[
   MultinormalDistribution[{40, -100}, 10 IdentityMatrix[2]], 500];
GeoHistogram[pts, Quantity[300, "Kilometers"], ColorFunction -> "Rainbow"]

pts = GeoPosition /@ RandomVariate[
   MultinormalDistribution[{51.5, -0.1}, 0.05 IdentityMatrix[2]], 300];
GeoSmoothHistogram[pts, ColorFunction -> "SunsetColors"]

